const path = require('path');
const { JSDOM, ResourceLoader } = require('jsdom');
const axe = require('axe-core');
const babel = require('@babel/core');

const dir = __dirname;

class LocalLoader extends ResourceLoader {
  fetch(url, options) {
    if (url.startsWith('file://')) return super.fetch(url, options);
    return super.fetch(url, options);
  }
}

(async () => {
  const html = fs.readFileSync(path.join(dir, 'index.html'), 'utf8');
  const css = fs.readFileSync(path.join(dir, 'styles.css'), 'utf8');
  const jsx = fs.readFileSync(path.join(dir, 'app.jsx'), 'utf8');
  const compiled = babel.transformSync(jsx, {
    presets: [['@babel/preset-env', { targets: { node: 'current' } }], '@babel/preset-react'],
  }).code;

  // Inline CSS, replace external scripts with require'd React
  let staticHtml = html
    .replace(/<link[^>]*styles\.css[^>]*>/, `<style>${css}</style>`)
    .replace(/<script[^>]*react[^>]*><\/script>/g, '')
    .replace(/<script[^>]*babel[^>]*><\/script>/g, '')
    .replace(/<script[^>]*app\.jsx[^>]*><\/script>/, '');

  const dom = new JSDOM(staticHtml, { runScripts: 'outside-only', pretendToBeVisual: true, url: 'http://localhost/' });
  const { window } = dom;
  window.React = require('react');
  window.ReactDOM = require('react-dom/client');
  // Make available as globals expected by compiled code
  window.eval(`var React = window.React; var ReactDOM = window.ReactDOM;`);
  window.eval(compiled);

  // Wait for render
  await new Promise(r => setTimeout(r, 100));

  const runAxe = async (label) => {
    const source = axe.source;
    window.eval(source);
    const results = await window.axe.run(window.document);
    console.log(`\n=== ${label}: ${results.violations.length} violations ===`);
    for (const v of results.violations) {
      console.log(`- [${v.impact}] ${v.id}: ${v.help}`);
      v.nodes.forEach(n => console.log('   ', n.target.join(' '), '|', (n.failureSummary||'').split('\n')[0]));
    }
    return results.violations.length;
  };

  let total = 0;
  total += await runAxe('initial');

  // Click submit (invalid)
  const form = window.document.querySelector('form');
  const submitBtn = window.document.querySelector('button[type="submit"]');
  // Simulate form submit
  submitBtn.click();
  await new Promise(r => setTimeout(r, 50));
  total += await runAxe('after invalid submit');

  // Check checkbox + submit
  const cb = window.document.getElementById('agree-terms');
  cb.click();
  submitBtn.click();
  await new Promise(r => setTimeout(r, 50));
  total += await runAxe('after success');

  process.exit(total === 0 ? 0 : 1);
})().catch(e => { console.error(e); process.exit(2); });

